/* Chapter 2 — Motivational Counseling and Brief Intervention. Source: SAMHSA TIP 35 (2019), pp. 17–33. Study content only from the book. */
window.MI_CHAPTERS.push({
  id: 2,
  title: 'Motivational Counseling and Brief Intervention',
  pages: '17–33',
  quote: { text: 'The prevalent clinical focus on denial and motivation as client traits was misguided. Indeed, client motivation clearly was a dynamic process responding to a variety of interpersonal influences including advice, feedback, goal setting, contingencies, and perceived choice among alternatives.', by: 'Miller & Rollnick, 2013, p. 374' },
  keyMessages: [
    'Personalized feedback about a client’s use of substances relative to others and level of health-related risk can enhance client motivation to change substance use behaviors.',
    'Counselor focus and motivational counseling strategies should be tailored to the client’s stage in the Stages of Change (SOC) model.',
    'Effective motivational counseling approaches can be brief — a brief intervention (BI) or brief treatment (BT) — or comprehensive, as in screening, brief intervention, and referral to treatment (SBIRT).'
  ],
  sections: [
    { id: 'elements', h: 'Elements of Effective Motivational Counseling', blocks: [
      { t: 'p', x: '<strong>Any clinical strategy that enhances client motivation for change is a motivational intervention.</strong> It can be counseling, assessment or feedback; it can run over multiple sessions or a single BI; and it can be used in specialty SUD treatment or in other healthcare settings.' },
      { t: 'p', x: 'The elements that matter in motivational counseling:' },
      { t: 'ol', items: ['FRAMES approach', 'Decisional balancing', 'Developing discrepancy between personal goals and current behavior', 'Flexible pacing', 'Maintaining contact with clients'] },
      { t: 'h3', x: 'FRAMES (Miller & Sanchez, 1994)' },
      { t: 'table', head: ['Letter', 'Element', 'What it means'], rows: [
        ['F', 'Feedback', 'On personal risk relative to population norms, given after substance use assessment.'],
        ['R', 'Responsibility', 'Responsibility for change is placed with the client.'],
        ['A', 'Advice', 'About changing substance use, given by the counselor nonjudgmentally.'],
        ['M', 'Menu of options', 'Treatment alternatives offered to the client.'],
        ['E', 'Empathic counseling style', 'Warmth, respect and understanding, demonstrated and emphasized by the counselor.'],
        ['S', 'Self-efficacy', 'Supported by the counselor to encourage client change.']
      ] },
      { t: 'p', x: 'FRAMES is often incorporated into SBIRT interventions and has been combined with other interventions and tested across settings and cultures.' }
    ] },
    { id: 'feedback', h: 'FRAMES: Feedback', blocks: [
      { t: 'p', x: 'Personalized feedback is effective in reducing substance misuse and other health-risk behaviors. It usually compares the client’s scores on standard screening or assessment instruments with normative data from the general population or treatment groups, and it should address cultural differences and norms — feedback tailored to the cultural and social aspects of drinking reduced drinking among Latino clients more than standard feedback.' },
      { t: 'note', title: 'Counselor note: motivational enhancement therapy (MET)', x: 'MET is an early offshoot of the “drinker’s check-up,” which gave clients nonjudgmental feedback about their drinking. It is a brief approach giving personalized, neutral, MI-style feedback; counselors elicit the client’s understanding of the feedback, reflect, and listen for signs the client is considering change. Research shows moderate to strong support for reductions in use versus no intervention. <strong>Personalized feedback alone is sometimes enough to move a client from Precontemplation to Contemplation.</strong>' },
      { t: 'h3', x: 'Before giving feedback: establish rapport' },
      { t: 'ul', items: [
        'Express appreciation for the client’s effort in providing the information.',
        'Ask whether answering questions or filling out forms was difficult; clarify specific questions.',
        'Make clear you may need the client’s help to interpret the findings accurately.',
        'Encourage questions — “Please stop me if you have a question or don’t understand something.”',
        'Stress that the instruments provide objective data, standardized and widely used.'
      ] },
      { t: 'h3', x: 'Exhibit 2.1 — The Drinker’s Pyramid Feedback (AUDIT)' },
      { t: 'p', x: 'Show the client the score on any instrument and explain what it means. The sample handout accompanies the WHO’s <strong>AUDIT</strong> (U.S. version in Appendix B); higher scores reflect more serious alcohol-related problems.' },
      { t: 'table', head: ['AUDIT item', 'What it flags', 'Risks listed on the handout'], rows: [
        ['Question 3', 'Binge drinking — e.g., 5 drinks for men or 4 for women within 2 hours on a single occasion', 'Immediate: crashes and accidents, falls and injuries, intimate partner violence, depressed mood, suicidal or homicidal thoughts or behavior, firearm injuries, alcohol poisoning, assaults and sexual assaults, unprotected sex, child abuse and neglect, property crime, fires'],
        ['Questions 1 and 2', 'Drinking above recommended limits — women (and men over 65): no more than 3 drinks a day and 7 a week; men 65 and younger: no more than 4 a day and 14 a week', 'Long-term: gastric distress, hypertension, cardiovascular disease, permanent liver damage, cancer, pancreatitis, diabetes, chronic depression, neurologic damage, fetal alcohol spectrum disorders']
      ] },
      { t: 'h3', x: 'Presenting feedback in a motivational style' },
      { t: 'p', x: 'Don’t pressure clients to accept a diagnosis or offer unsolicited opinions about the results. Preface with “I don’t know whether this will concern you, but …” and let clients draw their own conclusions: “What do you make of this?”' },
      { t: 'ul', items: [
        'Ask about the initial reaction: “Sometimes people learn surprising things when they complete an assessment. What were your reactions?”',
        'Use a handout or visual aid with scores, norms and risks — in the client’s first language.',
        'Be neutral, nonjudgmental and respectful; use easy, culturally appropriate language.',
        'Give small chunks of information.',
        'Use open questions and reflective listening to explore the client’s understanding and readiness.',
        'Summarize results, risks, reactions and any change talk, then ask the client to add to or correct the summary.',
        'Provide a written summary.'
      ] },
      { t: 'p', x: 'Clients react differently — one is alarmed at drinking more than peers but unconcerned about health risks, another is worried about the health risks. The key is to keep exploring the client’s understanding and what it suggests about change. Personalized feedback also applies to other behaviors such as tobacco use.' }
    ] },
    { id: 'rames', h: 'FRAMES: Responsibility to Self-efficacy', blocks: [
      { t: 'h3', x: 'Responsibility' },
      { t: 'p', x: 'Reinforce personal autonomy: clients choose whether to continue or change their use, or enter treatment — consistent with self-determination theory. When clients realize they are responsible for change they feel empowered and invested, with better outcomes.' },
      { t: 'ul', items: [
        'Ask permission to talk about their substance use; invite them to consider the information. Having choices lowers the need to oppose your ideas.',
        'State clearly that you won’t ask them to do anything they are unwilling to do.',
        'Determine a common agenda for each session.',
        'Agree on treatment goals acceptable to the client.'
      ] },
      { t: 'h3', x: 'Advice' },
      { t: 'p', x: 'Advice delivered in the MET/MI style can change drinking, drug and tobacco use. It is better not to tell people what to do — <em>suggestions yield better results</em>. Advice may be <strong>directive</strong> (a suggestion) or <strong>educational</strong> (information based on credible evidence, such as NIAAA safe drinking limits or the client’s blood alcohol level at a crash).' },
      { t: 'ul', items: [
        'Ask permission: “Would you like to hear about safe drinking limits?” “Can I tell you what tolerance to alcohol is?”',
        'Ask what the client thinks of your suggestions or information.',
        'If the client makes a specific request, ask for clarification before advising.',
        'Offer simple suggestions matched to understanding, readiness, urgency and culture — some cultures need a directive approach to convey importance; in others it is rude and intrusive.'
      ] },
      { t: 'note', title: 'Expert comment (Linda C. Sobell): a realistic model of change', x: 'Most change does not occur overnight. Change is a gradual process with occasional setbacks, like hiking up a bumpy hill. Difficulties and setbacks can be reframed as learning experiences, not failures.' },
      { t: 'note', title: 'Expert comment (Kenneth J. Hoffman): the PIES approach', x: 'World War I military psychiatrists found that well-timed motivational interventions returned many stressed soldiers to duty. <strong>Proximity</strong> — treat near the place of duty; don’t evacuate. <strong>Immediacy</strong> — intervene at the first sign. <strong>Expectancy</strong> — expect success and return to duty. <strong>Simplicity</strong> — listen, offer empathy, show understanding. The reactions are normal; it is the situation that is abnormal. Evacuation was reserved for the few who did not respond.' },
      { t: 'h3', x: 'Menu of options' },
      { t: 'p', x: 'Choices enhance the alliance, decrease dropout and improve outcomes; clients adhere better to a strategy they chose. Provide accurate information on each option and its implications, elicit which options they think would work or worked before, and brainstorm alternatives if none is acceptable. Your role is to enhance their ability to make informed choices (more in Chapter 6).' },
      { t: 'h3', x: 'Empathic counseling style' },
      { t: 'p', x: 'Highly empathic counselors are curious, explore the client’s ideas about their use, show active interest and encourage elaboration beyond the content of the story. Counselor empathy is a <strong>moderately strong predictor</strong> of outcomes. Reflective listening communicates empathy (Chapter 3); the client does most of the talking. It looks easy but takes training and effort, and it can be particularly effective in <strong>Precontemplation</strong>.' },
      { t: 'h3', x: 'Self-efficacy' },
      { t: 'p', x: 'Be supportive, identify strengths, review past successes and express optimism. Clients must believe they can do specific tasks in specific situations (Bandura, 1977). In addiction treatment, self-efficacy usually means the ability to identify high-risk situations that trigger the urge to use and to cope without returning to use. Ask: “How did you get from where you were to where you are now?” “How have you resisted the urge to use in stressful situations?” Affirm small steps.' }
    ] },
    { id: 'dbdp', h: 'Decisional Balancing, Discrepancy, Pacing and Contact', blocks: [
      { t: 'h3', x: 'Decisional balancing (Janis & Mann, 1977)' },
      { t: 'p', x: 'Ask the client to articulate the positive and negative aspects of using substances — the pros and cons of changing versus not changing (more in Chapter 5). <strong>The number of reasons on each side matters less than the weight — the personal value — of each.</strong> A 20-year-old smoker may care little about lung cancer but a lot about losing lung capacity for basketball.' },
      { t: 'h3', x: 'Developing discrepancy' },
      { t: 'p', x: 'Help clients see the gap between future goals and current behavior: “How does drinking fit or not fit with your goal of improving your family relationships?” When present actions conflict with important goals — health, job success, close relationships — change is more likely (Chapter 3).' },
      { t: 'h3', x: 'Flexible pacing' },
      { t: 'p', x: 'Assess readiness and <strong>resist the urge to go faster than the client’s pace</strong>. Some clients cycle back and forth; some need time to resolve ambivalence; a few are ready to act now. Suggesting Action steps to a client still in Contemplation can create discord. You may need frequent sessions early and fewer later, or allow a break. Pushing too fast can break down the alliance.' },
      { t: 'h3', x: 'Maintaining contact' },
      { t: 'p', x: 'Handwritten letters, calls, texts or emails encourage clients to return after a missed appointment and stay involved. The alliance is a significant factor in outcomes across methods; <strong>low alliance predicts dropout</strong>. Follow agency policy and ethics for contact outside sessions or after discharge (TIP 60).' }
    ] },
    { id: 'soc', h: 'Motivational Counseling and the SOC', blocks: [
      { t: 'p', x: 'Your job is to match treatment focus and strategies to the change processes the client is going through. Prochaska (1979) identified personal growth processes — <strong>catalysts for change</strong> — later applied to the SOC. <strong>Experiential</strong> catalysts are linked more with early stages; <strong>behavioral</strong> catalysts with later stages.' },
      { t: 'h3', x: 'Exhibit 2.2 — Catalysts for change' },
      { t: 'table', head: ['Catalyst', 'Client change process', 'Stage'], rows: [
        ['Consciousness raising', 'Experiential. Gains new awareness and understanding of substance use behavior.', 'Precontemplation / Contemplation'],
        ['Emotional arousal', 'Experiential. Motivated to contemplate change after an important emotional reaction to current use or to the need to change.', 'Precontemplation / Contemplation'],
        ['Environmental reevaluation', 'Experiential. Evaluates pros and cons of current use and its effects on others and the community.', 'Precontemplation / Contemplation'],
        ['Self-reevaluation', 'Experiential. Explores current use and the possibility of change in relation to own values.', 'Contemplation'],
        ['Social liberation', 'Experiential. Recognizes and increases available positive social supports.', 'Contemplation / Preparation'],
        ['Counterconditioning', 'Behavioral. Recognizes links between internal and external cues and use; experiments with substituting healthier behaviors in response to cues.', 'Preparation / Action'],
        ['Helping relationships', 'Behavioral. Seeks and cultivates relationships that support positive change.', 'Preparation / Action / Maintenance'],
        ['Self-liberation', 'Behavioral. Begins to believe in the ability to choose and change; develops self-efficacy and commits to changing.', 'Preparation / Action / Maintenance'],
        ['Stimulus control', 'Behavioral. Avoids stimuli and cues that could trigger use.', 'Action'],
        ['Reinforcement management', 'Behavioral. Self-rewards positive change and eliminates reinforcements for use.', 'Action / Maintenance']
      ] },
      { t: 'h3', x: 'Counselor focus in the SOC' },
      { t: 'p', x: 'Use supports that match the client’s stage. Using another stage’s strategies risks dropout or poor follow-through — arguing for change, or jumping to Preparation, with an ambivalent client in Contemplation makes the client likely to become reactive.' },
      { t: 'stages' },
      { t: 'table', head: ['Stage', 'Help the client to…', 'Counselor focus (Exhibit 2.3)'], rows: [
        ['Precontemplation', 'Consider change by increasing awareness of the need for change.', 'Build trust; raise doubt and concern.'],
        ['Contemplation', 'Resolve ambivalence by choosing positive change over the current situation.', 'Normalize ambivalence; tip the balance toward change.'],
        ['Preparation', 'Identify potential change strategies and choose the most appropriate.', 'Explore change goals; develop a change plan.'],
        ['Action', 'Carry out and follow through with the change strategies.', 'Support client action steps; evaluate the change plan.'],
        ['Maintenance', 'Develop new skills to maintain recovery and a lifestyle without misuse.', 'Stabilize client change; support lifestyle changes.'],
        ['Relapse & Recycle', 'If misuse resumes, recover as fast as possible.', 'Help the client re-enter the change cycle.']
      ] },
      { t: 'p', x: 'Chapters 4 through 7 cover the specific strategies for each stage.' }
    ] },
    { id: 'culture', h: 'Special Applications and Cultural Responsiveness', blocks: [
      { t: 'p', x: 'Motivational interventions (MI, MET, BI) are associated with retention, reduction in or abstinence from alcohol, cannabis, illicit drugs and tobacco, and fewer consequences — across ages, genders and racial and ethnic groups. They have been used stand-alone or as add-ons for diabetes, chronic pain, cardiovascular disease, HIV, CODs, eating disorders, OUD, and pregnant women who drink or use drugs.' },
      { t: 'p', x: 'The change process seems similar across populations, but expressions of motivation and the importance of life events can differ. MI was one of two evidence-based treatments endorsed as culturally appropriate by most surveyed programs serving American Indian and Alaska Native clients; an AI/AN adaptation uses a prayer and spiritual ceremonies to explain MI. MI’s collaboration, evocation and respect for autonomy fit well with African American clients, though some African American women may prefer less purely client-centered work — adaptations include peer delivery, moderate advice and community settings such as a church.' },
      { t: 'p', x: 'Respond nonjudgmentally to differences in the value of health, the meaning of time, the meaning of alcohol or drug use, and responsibilities to community and family. Understand the client’s perspective rather than impose mainstream values.' },
      { t: 'h3', x: 'Exhibit 2.4 — RESPECT: a mnemonic for cultural responsiveness' },
      { t: 'table', head: ['Letter', 'Principle', 'What to do'], rows: [
        ['R', 'Respect', 'Understand how respect is shown in different cultures; show it verbally and nonverbally.'],
        ['E', 'Explanatory model', 'Explore the client’s understanding of their use and cultural beliefs about misuse and how people change.'],
        ['S', 'Sociocultural context', 'Recognize how class, gender, race, ethnicity, sexual or gender identity, age, SES and other characteristics may affect treatment.'],
        ['P', 'Power', 'Acknowledge the power differential between counselor and client.'],
        ['E', 'Empathy', 'Express genuine interest in the client’s perspective and concerns.'],
        ['C', 'Concerns and fears', 'Elicit concerns about seeking help and entering treatment.'],
        ['T', 'Trust / therapeutic alliance', 'Trust must be earned; act in ways that enhance the relationship.']
      ] },
      { t: 'note', title: 'Expert comment (Rosalyn Harris-Offutt): culture and the change process', x: 'Culture shapes how people receive information, decide, pace and become ready to act. <strong>The responsibility for knowing different cultural value systems lies with the provider, not the client.</strong> Communication is culture-bound — a young American Indian man said he “might not be able to come back because his shoes were too tight,” meaning he had no money. Ethnicity and education do not determine the values a person lives by. If in doubt, explore the client’s beliefs with them.' },
      { t: 'p', x: 'Cultural values can also be barriers: some clients value respect from elders or group leaders, others find such groups unhelpful; some cultures welcome family in counseling, others find it disrespectful. Be sensitive to poverty, social isolation, historical trauma and recent losses — lack of resources makes change harder. Acknowledge the facts while affirming strengths and capacity for endurance and growth (TIP 59).' }
    ] },
    { id: 'cod', h: 'Adults With Co-Occurring Disorders', blocks: [
      { t: 'p', x: '2017 NSDUH: 46.6 million U.S. adults (19 percent) had any mental illness in the past year, including 11.2 million (4.5 percent) with serious mental illness (SMI). <strong>18 percent</strong> of those with any mental illness also had an SUD, versus 5 percent of adults without mental illness; almost <strong>28 percent</strong> of adults with SMI had a co-occurring SUD.' },
      { t: 'p', x: 'Even low levels of misuse can seriously affect people with SMI. AUD with major depressive disorder carries a greater burden than either alone. MI, and MI combined with CBT, reduce alcohol and cannabis use, depression and anxiety. Clients with COD find it harder to engage and stay in treatment, so interventions that engage, retain and improve adherence fit well.' },
      { t: 'ul', items: [
        'Meta-analysis in SMI with substance misuse (Hunt et al., 2013): MI was not generally more effective than other psychosocial treatments, but MI clients attended their <strong>first aftercare appointment</strong> significantly more often and had higher alcohol abstinence.',
        'MI-based interventions emphasizing adherence improved adherence and psychiatric symptoms.',
        '<strong>Dual Diagnosis MI (DDMI)</strong> increases task-specific motivation and adherence to cognitive training.'
      ] },
      { t: 'note', title: 'Counselor note: Dual Diagnosis Motivational Interviewing', x: 'DDMI is a <strong>two-session</strong> intervention for substance misuse in clients with <strong>psychotic disorders</strong>, with accommodations for cognitive impairment: simple questions and reflections; frequent repetition and summaries; more structure; sensitivity to emotional material; simple concrete examples; visual aids and written materials; restating information; a slower pace; pauses so clients can process.' },
      { t: 'note', title: 'Expert comment (Michael V. Pantalon): MI for adults with COD', x: 'Psychiatric inpatients randomized to standard discharge planning or standard care plus a motivational assessment, feedback at admission and a <strong>1-hour MI before discharge</strong>. The MI group attended its first outpatient appointment at <strong>two and a half times</strong> the rate — MI with virtually no modification worked, especially for clients with very low motivation. Asking why they would <em>not</em> attend aftercare had surprise value and built rapport. Instead of countering “I’m better now, I don’t need aftercare,” the team used open questions (“What do you think helped you get better?”) or an amplified reflection (“So you’re saying you probably won’t need any other treatment ever again”; for fragile clients, “It’s hard for you to imagine a reason why you might continue to need treatment”). Clients often countered their own statements. What mattered most was what they did <em>not</em> do: argue or dispute.' }
    ] },
    { id: 'bi', h: 'Brief Motivational Interventions', blocks: [
      { t: 'p', x: 'People who misuse substances are a far larger group than those needing specialized addiction treatment. BI strategies with motivational components are widely disseminated because of the need for a broader base of prevention and treatment for minimal-to-severe use, the need for cost-effective interventions under managed care, and consistent evidence of BI efficacy relative to no intervention.' },
      { t: 'p', x: '<strong>BI</strong> is a structured, person-centered approach delivered by trained health and behavioral health professionals in <strong>one to four sessions</strong>, typically <strong>5 to 30 minutes</strong>. Even single sessions with MET/MI components reduce use. BI is used most often in <strong>opportunistic settings</strong> outside specialty treatment, where people come for medical or mental health care, are routinely screened, and receive a BI if they misuse substances.' },
      { t: 'p', x: 'Its purpose: counsel about misuse patterns, raise awareness of negative effects, and advise limiting or stopping use. If there is no substantial improvement, refer for specialized treatment. A BI can also explore pros and cons of entering treatment, offer a menu of options and facilitate contact. <strong>FRAMES is the dominant BI method</strong> for substance misuse.' },
      { t: 'p', x: 'BI is also used in SUD programs for people on waiting lists, as a motivational prelude to more intensive treatment, and as a first attempt at change. <strong>A series of BIs can constitute brief treatment (BT)</strong> — motivational and other methods (e.g., CBT) for a limited time — particularly effective for clients who want to <em>abstain</em> rather than reduce. BT may be more effective than BI for illicit drug use.' },
      { t: 'note', title: 'Expert comment (Ed Bernstein): BI in the emergency department', x: 'It is a struggle to let go of being the expert in charge; the person is an expert in her own lifestyle, needs and choices. He asks permission to discuss substance use, asks what the person enjoys and enjoys less about using, reflects and summarizes, then asks, “Where does this leave you?” He asks readiness on a <strong>1-to-10 scale</strong> — if low, what would it take to move forward; if high, what would work. Interested clients explore pros and cons of choices, and an ED SUD specialist arranges placement and transport. It is ethical, respects autonomy, and is less time-consuming and frustrating.' }
    ] },
    { id: 'sbirt', h: 'Screening, Brief Intervention, and Referral to Treatment', blocks: [
      { t: 'p', x: 'SBIRT adds screening and referral to BI. It was developed specifically for <strong>nonspecialized settings</strong> — EDs, primary care, community health clinics, general inpatient units — and the SAMHSA multisite initiative is the largest U.S. dissemination effort. It reduces use and misuse in adolescents, young adults and adults and increases participation in follow-up care.' },
      { t: 'p', x: 'Screening determines the next step: a BI such as FRAMES, or <strong>referral to specialized treatment when the person meets criteria for moderate or severe SUD</strong>. From a public health view SBIRT is both <strong>prevention and treatment</strong>.' },
      { t: 'ul', items: [
        'Evidence for illicit drug use is mixed, but SAMHSA initiative data show lower alcohol consumption, alcohol misuse and illicit drug use.',
        'Starting <strong>buprenorphine in the ED</strong> increased engagement in specialty treatment and decreased illicit drug use.',
        'Motivational interventions in ED and public health settings reduced overdose risk behaviors and nonmedical opioid use.',
        'Evidence supports SBIRT across ages and cultures, with careful choice of screening tools and tailored BI and referrals.'
      ] }
    ] },
    { id: 'conclusion', h: 'Conclusion', blocks: [
      { t: 'p', x: 'Motivational interventions can be used in BI, in BT and throughout the SOC. Screening and FRAMES suit BI; developing discrepancy and decisional balancing suit longer, more intensive specialty treatment. Common to all: engaging clients, building trust through empathic listening, and respecting clients’ autonomy and cultural customs and perspectives.' }
    ] }
  ],
  highYield: [
    'Any clinical strategy that enhances client motivation for change is a <strong>motivational intervention</strong> — counseling, assessment or feedback.',
    'Five elements of effective motivational counseling: <strong>FRAMES, decisional balancing, developing discrepancy, flexible pacing, maintaining contact</strong>.',
    'FRAMES (Miller & Sanchez, 1994): <strong>F</strong>eedback, <strong>R</strong>esponsibility, <strong>A</strong>dvice, <strong>M</strong>enu of options, <strong>E</strong>mpathic style, <strong>S</strong>elf-efficacy. It is the <strong>dominant BI method</strong>.',
    'Personalized feedback compares the client’s scores to population norms; it alone can move a client from <strong>Precontemplation to Contemplation</strong>.',
    'MET grew from the <strong>drinker’s check-up</strong>: neutral, MI-style personalized feedback; moderate-to-strong support versus no intervention.',
    'Let clients interpret their results: “I don’t know what you’ll make of this, but…” then “What do you make of this?” Never pressure them to accept a diagnosis.',
    'AUDIT Q3 flags binge drinking (5 drinks men / 4 women within 2 hours); Q1–2 flag drinking above limits (women and men over 65: ≤3/day, ≤7/week; men ≤65: ≤4/day, ≤14/week).',
    'Advice works best as suggestion, after <strong>asking permission</strong>; it can be directive or educational.',
    'PIES: <strong>P</strong>roximity, <strong>I</strong>mmediacy, <strong>E</strong>xpectancy, <strong>S</strong>implicity — “reactions are normal; the situation is abnormal.”',
    'Counselor empathy is a <strong>moderately strong predictor</strong> of outcomes and especially useful in Precontemplation.',
    'Decisional balance: the <strong>weight</strong> of each reason matters more than the number of reasons.',
    'Flexible pacing: going faster than the client (e.g., Action steps in Contemplation) creates <strong>discord</strong>; low alliance predicts dropout.',
    'Catalysts for change: <strong>experiential</strong> (consciousness raising, emotional arousal, environmental reevaluation, self-reevaluation, social liberation) dominate early stages; <strong>behavioral</strong> (counterconditioning, helping relationships, self-liberation, stimulus control, reinforcement management) dominate later stages.',
    'Counselor focus: Precontemplation — build trust, raise doubt; Contemplation — normalize ambivalence, tip the balance; Preparation — explore goals, develop a plan; Action — support steps, evaluate the plan; Maintenance — stabilize change, support lifestyle; Recycle — help re-enter the cycle.',
    'RESPECT: <strong>R</strong>espect, <strong>E</strong>xplanatory model, <strong>S</strong>ociocultural context, <strong>P</strong>ower, <strong>E</strong>mpathy, <strong>C</strong>oncerns and fears, <strong>T</strong>rust/alliance.',
    'Responsibility for knowing cultural value systems lies with the <strong>provider</strong>, not the client.',
    'COD: 18% of adults with any mental illness had an SUD (vs 5% without); ~28% of adults with SMI had an SUD.',
    'DDMI: <strong>two sessions</strong> for substance misuse in <strong>psychotic disorders</strong>, adapted for cognitive impairment (simple, structured, slow, repeated, visual).',
    'Pantalon: a 1-hour MI before psychiatric discharge gave <strong>2.5×</strong> the rate of attending the first outpatient appointment.',
    'BI: <strong>1–4 sessions, 5–30 minutes</strong>, usually in opportunistic settings. A series of BIs = <strong>BT</strong>, better for clients aiming to abstain and possibly for illicit drugs.',
    'SBIRT: built for nonspecialized settings; screening decides BI vs referral (moderate or severe SUD); both prevention and treatment.',
    'ED-initiated <strong>buprenorphine</strong> increased engagement in specialty treatment and decreased illicit drug use.'
  ],
  cards: [
    { id: 'c01', tag: 'Basics', q: 'How does TIP 35 define a motivational intervention?', a: 'Any clinical strategy that enhances client motivation for change — including counseling, assessment and feedback, in one or many sessions, in specialty or other healthcare settings.' },
    { id: 'c02', tag: 'Basics', q: 'Name the five elements of effective motivational counseling.', a: 'FRAMES, decisional balancing, developing discrepancy, flexible pacing and maintaining contact with clients.' },
    { id: 'c03', tag: 'FRAMES', q: 'What does FRAMES stand for, and who described it?', a: 'Feedback, Responsibility, Advice, Menu of options, Empathic counseling style, Self-efficacy — Miller and Sanchez (1994).' },
    { id: 'c04', tag: 'FRAMES', q: 'What does personalized feedback usually compare?', a: 'The client’s scores on standard screening or assessment instruments with normative data from the general population or treatment groups.' },
    { id: 'c05', tag: 'FRAMES', q: 'Can personalized feedback alone move a client to a new stage?', a: 'Sometimes — it can be enough to move a client from Precontemplation to Contemplation without additional counseling.' },
    { id: 'c06', tag: 'MET', q: 'What is motivational enhancement therapy (MET), and what did it grow out of?', a: 'A brief approach giving personalized, neutral, MI-style feedback, eliciting the client’s understanding and listening for change. It is an early offshoot of the <strong>drinker’s check-up</strong>.' },
    { id: 'c07', tag: 'Feedback', q: 'List three ways to build rapport before giving a client their score.', a: 'Any three: thank them for providing the information; ask whether the forms were difficult; say you may need their help interpreting results; encourage questions; stress the instruments give objective, standardized data.' },
    { id: 'c08', tag: 'Feedback', q: 'How should you preface feedback and invite interpretation?', a: '“I don’t know whether this will concern you, but…” then “What do you make of this?” — let clients draw their own conclusions; don’t push a diagnosis.' },
    { id: 'c09', tag: 'AUDIT', q: 'Which AUDIT item flags binge drinking, and how is binge drinking defined on the handout?', a: 'Question 3 — e.g., 5 drinks for men or 4 for women within 2 hours on a single occasion.' },
    { id: 'c10', tag: 'AUDIT', q: 'What drinking limits does Exhibit 2.1 give?', a: 'Women and men over 65: no more than 3 drinks a day and 7 a week. Men 65 and younger: no more than 4 a day and 14 a week.' },
    { id: 'c11', tag: 'Feedback', q: 'After presenting feedback, what should your summary include, and what do you ask next?', a: 'Results, risks and problems, the client’s reactions and any change talk — then ask the client to add to or correct it. Give a written summary.' },
    { id: 'c12', tag: 'FRAMES', q: 'Give four strategies for emphasizing client responsibility.', a: 'Ask permission to discuss use; state you won’t ask them to do anything they’re unwilling to do; set a common agenda each session; agree on goals acceptable to the client.' },
    { id: 'c13', tag: 'FRAMES', q: 'What are the two forms motivational advice can take?', a: '<strong>Directive</strong> (making a suggestion) or <strong>educational</strong> (providing evidence-based information, e.g., NIAAA drinking limits).' },
    { id: 'c14', tag: 'FRAMES', q: 'What should you do before giving advice?', a: 'Ask permission — e.g., “Would you like to hear about safe drinking limits?” — and afterward ask what the client thinks of it.' },
    { id: 'c15', tag: 'Expert', q: 'What realistic model of change does Linda Sobell describe to clients?', a: 'Change rarely happens overnight; it is gradual with setbacks, like hiking up a bumpy hill; setbacks are learning experiences, not failures.' },
    { id: 'c16', tag: 'PIES', q: 'What does PIES stand for?', a: 'Proximity, Immediacy, Expectancy, Simplicity — a World War I military psychiatry approach to returning stressed soldiers to duty.' },
    { id: 'c17', tag: 'PIES', q: 'What is the core message given to the person in the PIES approach?', a: 'Their reactions are normal; it is the situation that is abnormal. They will recover with rest and nourishment.' },
    { id: 'c18', tag: 'FRAMES', q: 'What three strategies help you offer a menu of options?', a: 'Give accurate information on each option and its implications; elicit which options the client thinks would work or worked before; brainstorm alternatives if none is acceptable.' },
    { id: 'c19', tag: 'FRAMES', q: 'How strongly does counselor empathy predict outcomes, and in which stage is it particularly effective?', a: 'A moderately strong predictor (Elliott et al., 2018); particularly effective in Precontemplation.' },
    { id: 'c20', tag: 'FRAMES', q: 'In addiction treatment, what does self-efficacy usually refer to?', a: 'The client’s ability to identify high-risk situations that trigger the urge to use and to develop coping skills to manage the urge without returning to use.' },
    { id: 'c21', tag: 'Decisional balance', q: 'In a decisional balance sheet, what matters more than the number of reasons?', a: 'The weight — the personal value — of each reason.', why: 'A young smoker may care more about lung capacity for basketball than about lung cancer.' },
    { id: 'c22', tag: 'Discrepancy', q: 'Give an example question for developing discrepancy.', a: '“How does drinking fit or not fit with your goal of improving your family relationships?”' },
    { id: 'c23', tag: 'Pacing', q: 'What happens if you suggest Action-stage steps to a client in Contemplation?', a: 'It can create discord; pushing faster than the client’s pace can break down the treatment alliance.' },
    { id: 'c24', tag: 'Contact', q: 'What does low therapeutic alliance predict?', a: 'Higher risk of dropping out of treatment (Brorson et al., 2013).' },
    { id: 'c25', tag: 'Catalysts', q: 'Which type of catalyst for change is linked with earlier stages, and which with later stages?', a: 'Experiential catalysts with earlier stages; behavioral catalysts with later stages.' },
    { id: 'c26', tag: 'Catalysts', q: 'Name the five experiential catalysts for change.', a: 'Consciousness raising, emotional arousal, environmental reevaluation, self-reevaluation, social liberation.' },
    { id: 'c27', tag: 'Catalysts', q: 'Name the five behavioral catalysts for change.', a: 'Counterconditioning, helping relationships, self-liberation, stimulus control, reinforcement management.' },
    { id: 'c28', tag: 'Catalysts', q: 'A client avoids the bar and the friends he used with. Which catalyst, and which stage?', a: 'Stimulus control — Action.' },
    { id: 'c29', tag: 'Catalysts', q: 'A client substitutes jogging when stress cues the urge to drink. Which catalyst?', a: 'Counterconditioning (Preparation/Action).' },
    { id: 'c30', tag: 'Catalysts', q: 'A client weighs how her drinking affects her children and community. Which catalyst?', a: 'Environmental reevaluation (Precontemplation/Contemplation).' },
    { id: 'c31', tag: 'Catalysts', q: 'Which catalyst involves believing in one’s ability to change and committing to it?', a: 'Self-liberation (Preparation/Action/Maintenance).' },
    { id: 'c32', tag: 'SOC focus', q: 'Exhibit 2.3: what is the counselor focus in Precontemplation and in Contemplation?', a: 'Precontemplation: build trust; raise doubt and concern. Contemplation: normalize ambivalence; tip the balance toward change.' },
    { id: 'c33', tag: 'SOC focus', q: 'Exhibit 2.3: what is the counselor focus in Preparation, Action and Maintenance?', a: 'Preparation: explore change goals, develop a change plan. Action: support client action steps, evaluate the plan. Maintenance: stabilize change, support lifestyle changes.' },
    { id: 'c34', tag: 'SOC focus', q: 'What is the counselor’s focus in Relapse & Recycle?', a: 'Help the client re-enter the change cycle, recovering as quickly as possible.' },
    { id: 'c35', tag: 'Culture', q: 'What does the RESPECT mnemonic stand for?', a: 'Respect, Explanatory model, Sociocultural context, Power, Empathy, Concerns and fears, Trust/therapeutic alliance.' },
    { id: 'c36', tag: 'Culture', q: 'In RESPECT, what does “Explanatory model” ask you to explore?', a: 'The client’s understanding of their substance use and their cultural beliefs about misuse and how people change.' },
    { id: 'c37', tag: 'Culture', q: 'According to Rosalyn Harris-Offutt, who is responsible for awareness of different cultural value systems?', a: 'The provider, not the client.' },
    { id: 'c38', tag: 'Culture', q: 'Name three ways MI has been adapted for African American clients.', a: 'Training peers to deliver MI, incorporating moderate amounts of advice, and delivering MI in community settings such as a local church.' },
    { id: 'c39', tag: 'COD', q: 'What proportion of adults with any mental illness, and of those with SMI, had a co-occurring SUD (2017 NSDUH)?', a: '18 percent of adults with any mental illness (vs 5 percent without); almost 28 percent of adults with SMI.' },
    { id: 'c40', tag: 'COD', q: 'In the Hunt et al. (2013) meta-analysis of SMI with substance misuse, where did MI stand out?', a: 'MI was not generally more effective than other psychosocial treatments, but MI clients attended their first aftercare appointment significantly more often and had higher alcohol abstinence rates.' },
    { id: 'c41', tag: 'DDMI', q: 'What is DDMI and whom is it for?', a: 'Dual Diagnosis Motivational Interviewing — a two-session intervention for substance misuse in clients with psychotic disorders.' },
    { id: 'c42', tag: 'DDMI', q: 'List four DDMI accommodations for cognitive impairment.', a: 'Any four: simple questions and reflections; frequent repetition and summaries; more structure; sensitivity to emotional material; concrete examples; visual and written aids; restating; slower pace; pauses to process.' },
    { id: 'c43', tag: 'COD', q: 'In Pantalon’s study, how did a 1-hour MI before psychiatric discharge affect aftercare attendance?', a: 'Clients attended their first outpatient appointment at two and a half times the rate of standard care.' },
    { id: 'c44', tag: 'COD', q: 'A client says, “I’m better now, I don’t need aftercare.” What would Pantalon’s team say instead of arguing?', a: 'An open question (“What do you think helped you get better?”) or an amplified reflection (“So you’re saying you probably won’t need any other treatment ever again”).' },
    { id: 'c45', tag: 'BI', q: 'How many sessions and how long is a typical BI?', a: 'One to four sessions, typically 5 to 30 minutes.' },
    { id: 'c46', tag: 'BI', q: 'What are “opportunistic settings”?', a: 'Settings outside specialty addiction treatment where people come for medical or mental health care, not for SUD help, and are routinely screened for substance use.' },
    { id: 'c47', tag: 'BI', q: 'Name three reasons BI use has expanded.', a: 'The need for prevention and treatment covering minimal-to-severe use; the need for cost-effective interventions under managed care; consistent evidence of BI efficacy versus no intervention.' },
    { id: 'c48', tag: 'BT', q: 'What is brief treatment (BT) and for whom is it particularly effective?', a: 'A series of BIs applying motivational and other methods (e.g., CBT) for a limited time — particularly effective for clients who want to abstain rather than reduce.' },
    { id: 'c49', tag: 'BI', q: 'What does Ed Bernstein ask after summarizing in an ED BI?', a: '“Where does this leave you?” — followed by readiness on a 1-to-10 scale.' },
    { id: 'c50', tag: 'SBIRT', q: 'In SBIRT, what determines whether a person gets a BI or a referral?', a: 'Screening results — those meeting criteria for moderate or severe SUD are referred to specialized treatment; others receive a BI such as FRAMES.' },
    { id: 'c51', tag: 'SBIRT', q: 'From a public health perspective, SBIRT is seen as what?', a: 'Both a prevention and a treatment strategy.' },
    { id: 'c52', tag: 'SBIRT', q: 'What did initiating buprenorphine in the ED do?', a: 'Significantly increased engagement in specialty addiction treatment and decreased illicit drug use.' }
  ],
  quiz: [
    { id: 'q01', q: 'In FRAMES, the “M” stands for:', choices: ['Motivation', 'Menu of options', 'Monitoring', 'Mutual goals'], answer: 1, why: 'Feedback, Responsibility, Advice, Menu of options, Empathic style, Self-efficacy.' },
    { id: 'q02', q: 'Personalized feedback in motivational counseling usually compares the client’s screening scores with:', choices: ['The counselor’s clinical impression', 'The client’s family members’ scores', 'Normative data from the general population or treatment groups', 'DSM-5 diagnostic criteria only'], answer: 2, why: 'Feedback on personal risk relative to population norms is the “F” in FRAMES.' },
    { id: 'q03', q: 'Which is the most motivational way to introduce an AUDIT result?', choices: ['“Your score proves you have an alcohol use disorder.”', '“I don’t know what you’ll make of this, but your score is in the high-risk range. What do you make of it?”', '“You need to stop drinking right away.”', '“Most people with your score end up in hospital.”'], answer: 1, why: 'Preface neutrally, avoid pressuring the client to accept a diagnosis, and invite the client’s own interpretation.' },
    { id: 'q04', q: 'Motivational enhancement therapy is an early offshoot of:', choices: ['The Minnesota model', 'The drinker’s check-up', 'Contingency management', 'The PIES approach'], answer: 1, why: 'The drinker’s check-up gave nonjudgmental feedback about drinking; MET gives neutral, MI-style personalized feedback.' },
    { id: 'q05', q: 'Which counselor statement best supports the “Responsibility” element?', choices: ['“I won’t ask you to do anything you’re unwilling to do — the choice is yours.”', '“You have to attend all sessions or you’ll be discharged.”', '“I’ll decide your goals so you don’t have to worry.”', '“Your family needs you to change.”'], answer: 0, why: 'Responsibility reinforces autonomy: ask permission, set a common agenda, agree on acceptable goals, and leave the choice with the client.' },
    { id: 'q06', q: 'According to TIP 35, advice is most effective when it is:', choices: ['Delivered firmly without asking', 'Offered as a suggestion after asking permission', 'Given only in writing', 'Avoided altogether'], answer: 1, why: 'Telling people what to do is less effective; suggestions after asking permission yield better results.' },
    { id: 'q07', q: 'The “E” in PIES stands for:', choices: ['Empathy', 'Evacuation', 'Expectancy', 'Education'], answer: 2, why: 'Proximity, Immediacy, Expectancy (expect success and return to duty), Simplicity.' },
    { id: 'q08', q: 'A 20-year-old smoker lists three reasons to keep smoking and one to quit — losing lung capacity for basketball — and the one reason matters most to him. What does this illustrate?', choices: ['The number of reasons determines the decision', 'The weight of each reason matters more than the number', 'He is in Precontemplation', 'Decisional balance does not apply to young people'], answer: 1, why: 'In decisional balancing, personal value (weight) outweighs the count of reasons.' },
    { id: 'q09', q: 'A client in Contemplation is still ambivalent. The counselor gives her an action plan with a quit date. The most likely result is:', choices: ['Faster progress to Action', 'Discord, reactance or dropout', 'Improved self-efficacy', 'No effect'], answer: 1, why: 'Mismatching stage strategies creates discord and risks dropout; flexible pacing means meeting clients where they are.' },
    { id: 'q10', q: 'Which pair of catalysts for change are both experiential?', choices: ['Stimulus control and counterconditioning', 'Consciousness raising and self-reevaluation', 'Helping relationships and reinforcement management', 'Self-liberation and stimulus control'], answer: 1, why: 'Experiential: consciousness raising, emotional arousal, environmental reevaluation, self-reevaluation, social liberation.' },
    { id: 'q11', q: 'A client now rewards herself with a weekend trip for each sober month and has stopped keeping alcohol at home. Which catalyst?', choices: ['Emotional arousal', 'Social liberation', 'Reinforcement management', 'Consciousness raising'], answer: 2, why: 'Reinforcement management: self-rewarding positive change and eliminating reinforcements for use (Action/Maintenance).' },
    { id: 'q12', q: 'Per Exhibit 2.3, the counselor focus for a client in Precontemplation is to:', choices: ['Develop a change plan', 'Build trust and raise doubt and concern', 'Support action steps', 'Stabilize change'], answer: 1, why: 'Precontemplation: build trust, raise doubt and concern. Contemplation: normalize ambivalence, tip the balance.' },
    { id: 'q13', q: 'In the RESPECT mnemonic, “P” reminds the counselor to:', choices: ['Plan treatment for the client', 'Acknowledge the power differential between counselor and client', 'Praise every small step', 'Prescribe medication when indicated'], answer: 1, why: 'Respect, Explanatory model, Sociocultural context, Power, Empathy, Concerns and fears, Trust.' },
    { id: 'q14', q: 'A young man says he “might not be able to come back because his shoes were too tight.” Harris-Offutt’s point is that:', choices: ['He is resistant to treatment', 'Communication is culturally shaped — he meant he had no money', 'He needs referral for a podiatric problem', 'Ethnicity determines values'], answer: 1, why: 'Verbal and nonverbal communication is culture-bound; the provider is responsible for understanding cultural value systems.' },
    { id: 'q15', q: 'DDMI is best described as:', choices: ['A 12-session group therapy for depression', 'A two-session intervention for substance misuse in clients with psychotic disorders', 'A screening tool for co-occurring disorders', 'A medication protocol for dual diagnosis'], answer: 1, why: 'Dual Diagnosis MI is two sessions, adapted for cognitive impairment: simple, structured, slower, repeated and visual.' },
    { id: 'q16', q: 'In Pantalon’s study, psychiatric inpatients who received a 1-hour MI before discharge:', choices: ['Had no difference in aftercare attendance', 'Attended their first outpatient appointment at 2.5 times the rate of controls', 'Required major modifications to MI', 'Did worse if their motivation was very low'], answer: 1, why: 'MI with virtually no modification was effective, particularly for clients with very low motivation.' },
    { id: 'q17', q: 'A typical brief intervention consists of:', choices: ['One to four sessions lasting about 5 to 30 minutes', 'Eight weekly 1-hour sessions', 'A 28-day inpatient stay', 'Only a written handout'], answer: 0, why: 'BI is structured and person-centered: 1–4 sessions, typically 5–30 minutes; even single sessions work.' },
    { id: 'q18', q: 'Brief treatment (BT) differs from a single BI in that it:', choices: ['Never uses CBT', 'Is a series of BIs over a limited time and suits clients who want to abstain', 'Is only for adolescents', 'Requires inpatient admission'], answer: 1, why: 'A series of BIs constitutes BT, applying motivational and other methods; it may be more effective than BI for illicit drug use.' },
    { id: 'q19', q: 'In SBIRT, a patient whose screening shows moderate or severe SUD should receive:', choices: ['No intervention', 'A BI only', 'Referral to specialized addiction treatment', 'A confrontational intervention'], answer: 2, why: 'Screening determines a BI such as FRAMES versus referral when the person meets criteria for moderate or severe SUD.' },
    { id: 'q20', q: 'Which statement about SBIRT is correct per TIP 35?', choices: ['It was designed for specialty addiction programs', 'It is purely a prevention strategy', 'It was developed for nonspecialized settings and is both prevention and treatment', 'It is ineffective for alcohol use'], answer: 2, why: 'SBIRT was built for EDs, primary care and general medical settings and is viewed as both prevention and treatment.' }
  ],
  glossary: [
    { term: 'Motivational intervention', def: 'Any clinical strategy that enhances client motivation for change — counseling, assessment or feedback — in one or many sessions and in any setting.' },
    { term: 'FRAMES', def: 'Six elements of effective motivational counseling (Miller & Sanchez, 1994): Feedback, Responsibility, Advice, Menu of options, Empathic counseling style, Self-efficacy. The dominant brief intervention method for substance misuse.' },
    { term: 'Personalized feedback', def: 'Showing a client their scores on screening or assessment instruments compared with normative data, with the related risks, in a neutral MI style.' },
    { term: 'Motivational enhancement therapy', def: 'A brief motivational counseling approach, an early offshoot of the drinker’s check-up, providing personalized, neutral, MI-style feedback and eliciting the client’s response.', alt: ['MET'] },
    { term: 'Drinker’s check-up', def: 'An early approach that gave clients nonjudgmental feedback about their drinking; MET grew out of it.' },
    { term: 'AUDIT', def: 'Alcohol Use Disorders Identification Test — a World Health Organization instrument assessing alcohol consumption, drinking behaviors and alcohol-related problems; higher scores reflect more serious problems.', alt: ['Alcohol Use Disorders Identification Test'] },
    { term: 'Binge drinking', def: 'As defined on the TIP 35 AUDIT feedback handout: e.g., 5 drinks for men or 4 for women consumed within 2 hours on a single occasion.' },
    { term: 'PIES', def: 'World War I military psychiatry approach: Proximity, Immediacy, Expectancy, Simplicity — reactions are normal; the situation is abnormal.' },
    { term: 'Discrepancy', def: 'The gap between a client’s future goals or values and current behavior; developing it enhances motivation to change.', alt: ['developing discrepancy'] },
    { term: 'Flexible pacing', def: 'Meeting clients at their level and allowing as much time as they need for each stage’s tasks, resisting the urge to move faster than the client.' },
    { term: 'Therapeutic alliance', def: 'The working relationship between counselor and client; a significant factor in outcomes. Low alliance predicts dropout.', alt: ['treatment alliance'] },
    { term: 'Catalysts for change', def: 'Personal growth processes (Prochaska, 1979) applied to the SOC; experiential catalysts dominate early stages and behavioral catalysts later stages.' },
    { term: 'Consciousness raising', def: 'Experiential catalyst: gaining new awareness and understanding of one’s substance use (Precontemplation/Contemplation).' },
    { term: 'Emotional arousal', def: 'Experiential catalyst: being moved to contemplate change by an important emotional reaction to current use or to the need to change (Precontemplation/Contemplation).' },
    { term: 'Environmental reevaluation', def: 'Experiential catalyst: evaluating the pros and cons of current use and its effects on others and the community (Precontemplation/Contemplation).' },
    { term: 'Self-reevaluation', def: 'Experiential catalyst: exploring current use and the possibility of change in relation to one’s own values (Contemplation).' },
    { term: 'Social liberation', def: 'Experiential catalyst: recognizing and increasing available positive social supports (Contemplation/Preparation).' },
    { term: 'Counterconditioning', def: 'Behavioral catalyst: recognizing internal and external cues to use and substituting healthier behaviors in response (Preparation/Action).' },
    { term: 'Helping relationships', def: 'Behavioral catalyst: seeking and cultivating relationships that support positive change (Preparation/Action/Maintenance).' },
    { term: 'Self-liberation', def: 'Behavioral catalyst: believing in one’s ability to choose and change, developing self-efficacy and committing to change (Preparation/Action/Maintenance).' },
    { term: 'Stimulus control', def: 'Behavioral catalyst: avoiding stimuli and cues that could trigger substance use (Action).' },
    { term: 'Reinforcement management', def: 'Behavioral catalyst: self-rewarding positive change and eliminating reinforcements for use (Action/Maintenance).' },
    { term: 'RESPECT', def: 'Mnemonic for cultural responsiveness: Respect, Explanatory model, Sociocultural context, Power, Empathy, Concerns and fears, Trust/therapeutic alliance.' },
    { term: 'Explanatory model', def: 'The client’s own understanding of their substance use and cultural beliefs about misuse and how people change.' },
    { term: 'Co-occurring disorders', def: 'Co-occurring substance use and mental disorders.', alt: ['COD', 'CODs'] },
    { term: 'Serious mental illness', def: 'The most severe category of mental illness; in 2017, 4.5 percent of U.S. adults, almost 28 percent of whom had a co-occurring SUD.', alt: ['SMI'] },
    { term: 'Dual Diagnosis Motivational Interviewing', def: 'A modified, two-session MI for substance misuse in clients with psychotic disorders, with accommodations for cognitive impairment.', alt: ['DDMI'] },
    { term: 'Amplified reflection', def: 'A reflection that states the client’s point more strongly than they did (e.g., “So you’re saying you probably won’t need any other treatment ever again”), often prompting the client to counter it.' },
    { term: 'Brief intervention', def: 'A structured, person-centered motivational counseling approach of 1–4 sessions, typically 5–30 minutes, used mostly in opportunistic settings.', alt: ['BI'] },
    { term: 'Brief treatment', def: 'A series of brief interventions applying motivational and other methods (e.g., CBT) for a limited time; well suited to clients who want to abstain.', alt: ['BT'] },
    { term: 'Opportunistic settings', def: 'Settings outside specialty addiction treatment (EDs, primary care, clinics) where people seek other care and can be screened and offered a BI.' }
  ]
});
